# Break My Fix finding 2, generated by Tracefix: try_update_year_range returns a wrong value.
# Property (issue): Every line of the license header (index..index+length) that contains a year ends up listing the current year, so multiple year lines are updated in a single run, not just the first one.
# Quote: If one of the pre-commit runs could be avoided by changing both lines in a single run that would be great.
# Run it with pytest: it fails for as long as the code breaks this property.

import datetime
import re

from pre_commit_hooks.insert_license import try_update_year_range


def test_break_my_fix_2() -> None:
    src_file_content = ['/* Copyright (c) 2012-2023 Dummy             */\n', '/*********************************************/\n', '/* @copyright Copyright (c) 2012-2023 Dummy  */\n', '<?php\n']
    src_filepath = 'file.php'
    license_header_index = 0
    license_length = -1
    result = try_update_year_range(src_file_content=['/* Copyright (c) 2012-2023 Dummy             */\n', '/*********************************************/\n', '/* @copyright Copyright (c) 2012-2023 Dummy  */\n', '<?php\n'], src_filepath=src_filepath, license_header_index=license_header_index, license_length=license_length)
    assert (all(str(datetime.datetime.now().year) in l for l in result[0][license_header_index:license_header_index + license_length] if re.search(r'(19|20)\d\d', l)))
